int pqcp_runtime_continuity_policy_lookup(
	enum pqcp_runtime_continuity_condition condition,
	enum pqcp_runtime_command_kind command,
	struct pqcp_runtime_continuity_policy_decision *decision)
{
	if (condition < PQCP_RUNTIME_CONTINUITY_HEALTHY ||
	    condition >= PQCP_RUNTIME_CONTINUITY_CONDITION_COUNT ||
	    command < PQCP_RUNTIME_COMMAND_NONE ||
	    command >= PQCP_RUNTIME_COMMAND_KIND_COUNT ||
	    decision == NULL) {
		return -EINVAL;
	}
	*decision = runtime_continuity_catalog[condition][command];
	return 0;
}

int pqcp_runtime_continuity_policy_catalog_audit(void)
{
	for (size_t condition = 0U;
	     condition < PQCP_RUNTIME_CONTINUITY_CONDITION_COUNT; ++condition) {
		for (size_t operation = 0U;
		     operation < PQCP_RUNTIME_POLICY_COMMAND_COUNT; ++operation) {
			const struct pqcp_runtime_continuity_policy_decision *entry =
				&runtime_continuity_catalog[condition][operation];

			if ((size_t)entry->condition != condition ||
			    (size_t)entry->command != operation ||
			    entry->directive >
				PQCP_RUNTIME_CONTINUITY_TERMINATE ||
			    entry->reason_mask == 0U) {
				return -EBADMSG;
			}
			if (entry->next_state < PQCP_RUNTIME_POLICY_UNINITIALIZED ||
			    entry->next_state > PQCP_RUNTIME_POLICY_TERMINATED) {
				return -EBADMSG;
			}
			if (entry->directive ==
				    PQCP_RUNTIME_CONTINUITY_DENY &&
			    entry->error == 0) {
				return -EBADMSG;
			}
		}
	}
	return 0;
}
